<?phpif (!defined('BASEPATH')) exit('No direct script access allowed');class Commonusermodel extends CI_Model {    public function fnGetInfo($VarEmailId = '', $VarStatus = '', $VarUserId = '', $VarCompanyId = '') {        //$this->db->select('id,contactname,mobile,username,status,desgnid,desgn')->from(KN_USERS)->join(KN_USER_DESGN,'desgnid = designationid');        $this->db->select('id,contactname,mobile,username,status,desgnid')->from(KN_USERS);        if ($VarStatus <> '') {            $this->db->where_in('status', array($VarStatus));        } else {            $this->db->where_in('status', array(1, 2));        }        if ($VarUserId <> '') {            $ArrWhere['id'] = $VarUserId;        }        if ($VarEmailId <> '') {            $ArrWhere['username'] = $VarEmailId;        }        /*if ($VarCompanyId <> '') {            $ArrWhere['companyid'] = $VarCompanyId;        }*/        if (!empty($ArrWhere)) {            $this->db->where($ArrWhere);        }        $ArrResultList = $this->db->get()->result_array();        return $ArrResultList;    }    function fnCheck($VarData = '', $VarId = '') {        $this->db->from(KN_USERS);        $ArrWhere = array('status' => "1");        if ($VarId <> '') {            $this->db->where_not_in('id', array($VarId));        }        if ($VarData <> '') {            $ArrWhere['username'] = $VarData;        }        $countAll = $this->db->where($ArrWhere)->count_all_results();        return $countAll;    }    public function saveMerchantUser($ArrUpdateData) {        $VarId = $ArrUpdateData['id'];        if ($VarId == "") {            $ArrCheckExist = $this->fnGetInfo($ArrUpdateData['username'], 1, '');            if (empty($ArrCheckExist)) {                unset($ArrUpdateData['id']);                $this->db->insert(KN_USERS, $ArrUpdateData);                $VarUserId = $this->db->insert_id();                $VarSql = 'SELECT COUNT(*) as nos FROM '.KN_USERS.' WHERE companyid = '.$ArrUpdateData['companyid'].' AND status = 1';                $Result = $this->db->query($VarSql)->result();                $VarCompanyUserNo = empty($Result[0]->nos) ? 0 : $Result[0]->nos;                $this->db->insert(KN_MERCHANT_TEAM, array('merchantid'=>$VarUserId,'companyid'=>$ArrUpdateData['companyid']));                $ArrShortForm = UT_SHORT_FORM;                $VarUserTypeCode = $ArrShortForm[3];                $VarCode = $ArrUpdateData['companyid'].'/'.$VarUserTypeCode.'-'.$VarCompanyUserNo.'/'.$VarUserId;                $ArrCadData = array('userid' => $VarUserId, 'code' => $VarCode);                $this->db->insert(KN_USER_DETAILS, $ArrCadData);                $ArrResult['errcode'] = 1;                $ArrResult['msg'] = '';                $ArrResult['id'] = $VarId;                $ArrResult['eid'] = urlencode(base64_encode($VarUserId));            } else {                $ArrResult['errcode'] = -1;                $ArrResult['msg'] = "This E-mail Id already exists";            }        } else {            $ArrCheckExist = $this->fnCheck($ArrUpdateData['username'], $VarId);            if (empty($ArrCheckExist)) {                $this->db->update(KN_USERS, $ArrUpdateData, array('id' => $VarId));                $ArrResult['errcode'] = 1;                $ArrResult['msg'] = '';                $ArrResult['id'] = $VarId;                $ArrResult['eid'] = urlencode(base64_encode($VarId));            } else {                $ArrResult['errcode'] = -1;                $ArrResult['msg'] = 'This E-mail Id already exists';            }        }        return $ArrResult;    }    public function saveUser($ArrUpdateData) {        $VarId = $ArrUpdateData['id'];        if ($VarId == "") {            $ArrCheckExist = $this->fnGetInfo($ArrUpdateData['username'], 1, '');            if (empty($ArrCheckExist)) {                unset($ArrUpdateData['id']);                $this->db->insert(KN_USERS, $ArrUpdateData);                $VarUserId = $this->db->insert_id();                $VarSql = 'SELECT COUNT(*) as nos FROM '.KN_USERS.' WHERE companyid = '.$ArrUpdateData['companyid'].' AND status = 1';                $Result = $this->db->query($VarSql)->result();                $VarCompanyUserNo = empty($Result[0]->nos) ? 0 : $Result[0]->nos;                $ArrShortForm = UT_SHORT_FORM;                $VarUserTypeCode = $ArrShortForm[$ArrUpdateData['usertype']];                $VarCode = $ArrUpdateData['companyid'].'/'.$VarUserTypeCode.'-'.$VarCompanyUserNo.'/'.$VarUserId;                $ArrCadData = array('userid' => $VarUserId, 'code' => $VarCode);                $this->db->insert(KN_USER_DETAILS, $ArrCadData);                $ArrResult['errcode'] = 1;                $ArrResult['msg'] = '';                $ArrResult['id'] = $VarId;                $ArrResult['eid'] = urlencode(base64_encode($VarUserId));            } else {                $ArrResult['errcode'] = -1;                $ArrResult['msg'] = "This E-mail Id already exists";            }        } else {            $ArrCheckExist = $this->fnCheck($ArrUpdateData['username'], $VarId);            if (empty($ArrCheckExist)) {                $this->db->update(KN_USERS, $ArrUpdateData, array('id' => $VarId));                $ArrResult['errcode'] = 1;                $ArrResult['msg'] = '';                $ArrResult['id'] = $VarId;                $ArrResult['eid'] = urlencode(base64_encode($VarId));            } else {                $ArrResult['errcode'] = -1;                $ArrResult['msg'] = 'This E-mail Id already exists';            }        }        return $ArrResult;    }    public function whereCond($VarName = '', $VarMobile='',$VarDesgnId='',$VarStatus = '',$VarUserType='',$VarCompanyId='') {        if ($VarName <> '') {            $ArrWhere[] = "contactname LIKE '%" . $VarName . "%'";        }        if ($VarMobile <> '') {            $ArrWhere[] = "mobile LIKE '%" . $VarMobile . "%'";        }        if ($VarDesgnId <> '') {            $ArrWhere[] = "desgnid = '" . $VarDesgnId . "'";        }        if ($VarStatus <> '') {            $ArrWhere[] = "status = " . $VarStatus;        } else {            $ArrWhere[] = "status in(1,2)";        }        if ($VarUserType <> '') {            $ArrWhere[] = "usertype = ".$VarUserType;        }        if ($VarCompanyId <> '') {            $ArrWhere[] = "u.companyid = ".$VarCompanyId;        }        $VarWhere = " WHERE ". implode(" AND ", $ArrWhere);        return $VarWhere;    }    public function fnCount($VarName = '', $VarMobile='',$VarDesgnId='',$VarStatus = '',$VarUserType='',$VarCompanyId='') {        $VarWhere = $this->whereCond($VarName, $VarMobile,$VarDesgnId,$VarStatus,$VarUserType,$VarCompanyId);        $VarSql = "SELECT count(1) as trec  FROM " . KN_USERS . " AS u INNER JOIN ".KN_USER_DESGN." As d ON u.desgnid = d.designationid " . $VarWhere;        $ObjRows = $this->db->query($VarSql)->row();        return $ObjRows->trec;    }    function fnList($VarName = '', $VarMobile='',$VarDesgnId='',$VarStatus = '', $VarUserType='',$VarCompanyId='',$VarLimit = 10, $offset = 0, $VarSortBy, $VarSortOrder) {        $VarSortOrder = ($VarSortOrder == 'desc') ? 'desc' : 'asc';        $VarSortCols = $this->ArrDbCols;        $VarSortBy = (in_array($VarSortBy, $VarSortCols)) ? $VarSortBy : 'dateupdated';        $VarLimitInfo = $VarLimit;        if ($offset >= 1) {            $VarLimitInfo = $offset . "," . $VarLimit;        }        $VarWhere = $this->whereCond($VarName, $VarMobile,$VarDesgnId,$VarStatus,$VarUserType,$VarCompanyId);        $VarSql = "SELECT id,contactname,mobile,username,dateupdated,status,updatedby,desgn FROM " . KN_USERS . " AS u INNER JOIN ".KN_USER_DESGN." As d ON         u.desgnid = d.designationid " . $VarWhere . " order by " . $VarSortBy . " " . $VarSortOrder . " limit " . $VarLimitInfo;        $ArrObjResult = $this->db->query($VarSql)->result();        $ArrUpdatedbyId = $ArrUpdatedBy = [];        if (!empty($ArrObjResult)) {            foreach ($ArrObjResult as $Obj) {                $ArrUpdatedbyId[] = $Obj->updatedby;            }        }        if(!empty($ArrUpdatedbyId)) {            $ArrObjUserInfo = $this->commonmodel->getUserInfo('', '', '', $ArrUpdatedbyId);            if (!empty($ArrObjUserInfo)) {                foreach ($ArrObjUserInfo as $userObj) {                    $ArrUpdatedBy[$userObj['id']] = $userObj['contactname'];                }            }        }        return array('listData' => $ArrObjResult, 'updatedByData' => $ArrUpdatedBy);        //return $this->db->query($VarSql);    }    public function changeStatus($ArrIds,$VarActDeactOption) {        $this->db->where_in('id', $ArrIds);        if($this->db->update(KN_USERS, array('status' => $VarActDeactOption))) $ArrResult = array('errcode'=>1);        else $ArrResult = array('errcode'=>-1);        return $ArrResult;    }}